//! Actions-only real AccountManager/current Common peer; no device business IO.
use super::*;
use n::buddy_relation_check::NativeBuddyRelationCheckConfig;
fn check_config(root:&str,port:u16,enabled:bool,timeout:u64)->AccountConfig{let mut c=directory_config(root,port,timeout,false,false);c.profile.buddy_relation_check=enabled.then_some(NativeBuddyRelationCheckConfig{check:true});c}
fn result(accepted:bool,ty:u32)->Vec<u8>{let mut w=Writer::new();w.boolean(accepted).unwrap();w.u32(ty).unwrap();w.bytes(b"").unwrap();w.properties(&[RpcProperty{key:b"private-footer",value:b"not-permission"}]).unwrap();w.finish().expose_to_transport().to_vec()}
async fn check_packet(peer:&mut CommonPeer,last:&mut Option<i32>)->i32{loop{let packet=peer.next().await.unwrap();assert_eq!(packet[0],0);let r=decode_request(&packet[1..]).unwrap();if r.method==n::buddy_relation_check::METHOD.as_bytes(){observe_id(last,r.call_id);assert_eq!(r.metadata.len(),2);assert_eq!(r.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"#Group");assert_eq!(r.metadata.iter().find(|p|p.key==b"token").unwrap().value,b"fixture-auth");let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"1_2");a.finish().unwrap();return r.call_id;}ordinary_poll(peer,&packet,last).await;}}
enum CheckStep{Read{seen:oneshot::Sender<i32>,release:oneshot::Receiver<()>,accepted:bool,ty:u32},Barrier(oneshot::Sender<()>),Finish}
struct CheckFixture{temp:TempDatabase,manager:AccountManager,line:String,steps:mpsc::Sender<CheckStep>,task:tokio::task::JoinHandle<()>}
impl CheckFixture{
 async fn new(enabled:bool,timeout:u64)->Self{let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(check_config(&cert.root,port,enabled,timeout),100).await.unwrap().account;let line=account.line_id.clone();let(steps,mut rx)=mpsc::channel(8);let task=tokio::spawn(Box::pin(bounded(async move{let original=listener.into_std().unwrap();let watch=TcpListener::from_std(original.try_clone().unwrap()).unwrap();let mut p=CommonPeer::open(TcpListener::from_std(original).unwrap(),server).await;let bytes=p.next().await.unwrap();let login=decode_request(&bytes[1..]).unwrap();p.send(&[reply(login.call_id,&login_result())]).await;let(_,flag)=hosting_call(&mut p).await;assert_eq!(flag,b"4");let mut last=None;while let Some(step)=rx.recv().await{match step{CheckStep::Read{seen,release,accepted,ty}=>{let id=check_packet(&mut p,&mut last).await;seen.send(id).unwrap();release.await.unwrap();p.send(&[reply(id,&result(accepted,ty))]).await;},CheckStep::Barrier(seen)=>{negative_barrier(&mut p,&mut last).await;seen.send(()).unwrap();},CheckStep::Finish=>{finish_account(&mut p).await;no_extra_connection(&watch).await;break;}}}})));bounded(manager.start(&line,1,100)).await.unwrap();bounded(async{while manager.get(&line,100).await.unwrap().phase!="hosted"{tokio::task::yield_now().await;}}).await;assert_eq!(manager.get(&line,100).await.unwrap().buddy_relation_check_supported,Some(enabled));Self{temp,manager,line,steps,task}}
 async fn plan(&self,accepted:bool,ty:u32)->(oneshot::Receiver<i32>,oneshot::Sender<()>){let(seen,rx)=oneshot::channel();let(tx,release)=oneshot::channel();self.steps.send(CheckStep::Read{seen,release,accepted,ty}).await.unwrap();(rx,tx)}
 async fn barrier(&self){let(tx,rx)=oneshot::channel();self.steps.send(CheckStep::Barrier(tx)).await.unwrap();bounded(rx).await.unwrap();}
 fn no_business(&self){assert!(self.manager.relation_write_history(&self.line,128).unwrap().is_empty());assert!(self.manager.relation_intent_history(&self.line,128).unwrap().is_empty());assert!(self.manager.im_messages(&self.line,128).unwrap().is_empty());assert!(self.manager.messages(&self.line,128).unwrap().is_empty());assert!(self.temp.database.get_recent_app_events(Some(&self.line),128).unwrap().is_empty());}
 async fn finish(self){self.steps.send(CheckStep::Finish).await.unwrap();assert!(!bounded(self.manager.stop(&self.line,1,100)).await.unwrap().io_cleanup_required);bounded(self.task).await.unwrap();assert!(!self.temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&self.line)).unwrap());}
}
#[tokio::test]async fn buddy_check_account_explicit_read_reports_u32_only_no_directory_write_or_extra_connection(){Box::pin(async{let f=CheckFixture::new(true,3000).await;assert_eq!(f.manager.get(&f.line,100).await.unwrap().directory_queries_supported,Some(false));for accepted in [true,false]{let p=f.manager.prepare_buddy_relation_check(&f.line,1,"1_2",true).unwrap();let(rx,go)=f.plan(accepted,u32::MAX).await;let mut op=Box::pin(f.manager.finish_buddy_relation_check(p));tokio::select!{r=&mut op=>panic!("unsubmitted {r:?}"),v=bounded(rx)=>{v.unwrap();}}go.send(()).unwrap();let v=bounded(op).await.unwrap();assert_eq!(serde_json::to_value(v).unwrap(),serde_json::json!({"accepted":accepted,"relation_type":4294967295u32}));f.no_business();}f.finish().await;}).await;}
#[tokio::test]async fn buddy_check_account_consent_revision_invalid_target_and_absent_policy_are_no_io(){Box::pin(async{for enabled in [false,true]{let f=CheckFixture::new(enabled,3000).await;assert_eq!(f.manager.prepare_buddy_relation_check(&f.line,1,"1_2",false).err(),Some("app_account_buddy_check_consent_required"));assert_eq!(f.manager.prepare_buddy_relation_check(&f.line,2,"1_2",true).err(),Some("app_account_revision_conflict"));assert_eq!(f.manager.prepare_buddy_relation_check(&f.line,1,"+12345",true).err(),Some("app_account_buddy_check_request_invalid"));if !enabled{assert_eq!(f.manager.prepare_buddy_relation_check(&f.line,1,"1_2",true).err(),Some("app_account_buddy_check_not_installed"));}else{let p=f.manager.prepare_buddy_relation_check(&f.line,1,"1_2",true).unwrap();drop(p);}f.barrier().await;assert_eq!(f.manager.im_send_resources_for_test(&f.line).unwrap(),(0,0));f.no_business();f.finish().await;}}).await;}
#[tokio::test]async fn buddy_check_account_controller_wait_keeps_original_deadline_and_no_query_after_timeout(){Box::pin(async{let f=CheckFixture::new(true,100).await;let(held,at)=oneshot::channel();let(release,wait)=oneshot::channel();let mut holding=Box::pin(f.manager.im_send_controller_pause_for_test(&f.line,held,wait));tokio::select!{r=&mut holding=>panic!("controller {r:?}"),r=at=>r.unwrap()};let p=f.manager.prepare_buddy_relation_check(&f.line,1,"1_2",true).unwrap();assert!(f.manager.im_send_resources_for_test(&f.line).unwrap().1>0);assert_eq!(bounded(f.manager.finish_buddy_relation_check(p)).await.err(),Some("app_account_directory_timeout"));release.send(()).unwrap();bounded(holding).await.unwrap();f.barrier().await;assert_eq!(f.manager.im_send_resources_for_test(&f.line).unwrap(),(0,0));f.no_business();f.finish().await;}).await;}
#[tokio::test]async fn buddy_check_account_same_revision_blob_change_between_prepare_and_finish_is_no_io(){Box::pin(async{let f=CheckFixture::new(true,3000).await;let p=f.manager.prepare_buddy_relation_check(&f.line,1,"1_2",true).unwrap();let raw=f.temp.database.with_conn(|c|{let b:Vec<u8>=c.query_row("SELECT private_config FROM app_voice_accounts WHERE line_id=?1",[&f.line],|r|r.get(0)).map_err(|_|"fixture")?;c.execute("UPDATE app_voice_accounts SET private_config=X'00' WHERE line_id=?1",[&f.line]).map_err(|_|"fixture")?;Ok(b)}).unwrap();assert!(bounded(f.manager.finish_buddy_relation_check(p)).await.is_err());f.temp.database.with_conn(|c|c.execute("UPDATE app_voice_accounts SET private_config=?2 WHERE line_id=?1",rusqlite::params![f.line,raw]).map_err(|_|"fixture")).unwrap();f.barrier().await;f.no_business();f.finish().await;}).await;}
#[tokio::test]async fn buddy_check_account_submitted_read_cancel_discards_late_result_keeps_sdk_no_retry(){Box::pin(async{let f=CheckFixture::new(true,3000).await;let p=f.manager.prepare_buddy_relation_check(&f.line,1,"1_2",true).unwrap();let(rx,go)=f.plan(true,12).await;let mut op=Box::pin(f.manager.finish_buddy_relation_check(p));tokio::select!{r=&mut op=>panic!("unsubmitted {r:?}"),v=bounded(rx)=>{v.unwrap();}}drop(op);bounded(f.manager.im_send_actor_barrier_for_test(&f.line,1)).await.unwrap();go.send(()).unwrap();f.barrier().await;assert_eq!(f.manager.get(&f.line,100).await.unwrap().phase,"hosted");f.no_business();f.finish().await;}).await;}
#[tokio::test]async fn buddy_check_account_unknown_relation_write_row_remains_untouched_after_check(){Box::pin(async{let f=CheckFixture::new(true,3000).await;f.temp.database.with_conn(|c|c.execute("INSERT INTO app_voice_relation_writes(line_id,revision,user_nonce,intent_hash,identity_key,run_nonce,scope_epoch,target_kind,additions,updates,removals,state,updated_at) VALUES(?1,1,?2,zeroblob(32),zeroblob(32),'original','original','buddy',1,0,0,0,'2026-01-01T00:00:00Z')",rusqlite::params![f.line,"a".repeat(32)]).map_err(|_|"fixture")).unwrap();let p=f.manager.prepare_buddy_relation_check(&f.line,1,"1_2",true).unwrap();let(rx,go)=f.plan(true,0).await;let mut op=Box::pin(f.manager.finish_buddy_relation_check(p));tokio::select!{r=&mut op=>panic!("unsubmitted {r:?}"),v=bounded(rx)=>{v.unwrap();}}go.send(()).unwrap();assert!(bounded(op).await.unwrap().accepted);let rows=f.manager.relation_write_history(&f.line,128).unwrap();assert_eq!(rows.len(),1);assert_eq!(rows[0].state,"uncertain");assert!(rows[0].base_time.is_none());assert!(f.temp.database.get_recent_app_events(Some(&f.line),128).unwrap().is_empty());f.finish().await;}).await;}
